import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** A template field line whose value was never filled in, e.g. `- **Retention**:` - used only as a
 *  fallback when a line isn't recognized by the field parser below (see extractSignoff). */
const EMPTY_FIELD = /^\s*[-*]\s*\*\*[^*]+\*\*.*:\s*$/;
const NEEDS_HUMAN_INPUT = /needs\s+human\s+input/i;

/** A field label where the trailing colon sits inside the bold markers: `- **Retention:** 30 days`. */
const FIELD_COLON_INSIDE = /^(\s*)[-*]\s*\*\*([^*:]+):\*\*\s*(.*)$/;
/** A field label where the colon sits outside the bold markers, optionally after a parenthetical
 *  hint: `- **Retention**: 30 days` or `- **Retention** (how long):`. */
const FIELD_COLON_OUTSIDE = /^(\s*)[-*]\s*\*\*([^*]+)\*\*[^:]*:\s*(.*)$/;
/** Deeper-indented lines belong to the field above (nested bullets, an indented table or paragraph)
 *  rather than starting a new field. */
const FIELD_INDENT_LIMIT = 2;

interface Section {
  heading: string;
  body: string;
}

interface FieldEntry {
  label: string;
  /** Raw text of the field's own bulleted line, used in "unanswered field" messages. */
  raw: string;
  /** The field's full answer: the inline value plus any nested continuation lines, trimmed. */
  text: string;
  isEmpty: boolean;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function matchFieldLine(line: string): { label: string; value: string } | null {
  const indent = line.length - line.trimStart().length;
  if (indent >= FIELD_INDENT_LIMIT) return null;
  const inside = line.match(FIELD_COLON_INSIDE);
  if (inside) return { label: inside[2].trim(), value: inside[3].trim() };
  const outside = line.match(FIELD_COLON_OUTSIDE);
  if (outside) return { label: outside[2].trim(), value: outside[3].trim() };
  return null;
}

/** Splits a gate subsection's body into its bulleted fields. A field's answer may continue on
 *  indented lines below it (nested bullets, an indented table or paragraph); blank lines in
 *  between are allowed. */
function parseFields(body: string): FieldEntry[] {
  const lines = body.split(/\r?\n/);
  const fields: FieldEntry[] = [];
  let current: { label: string; raw: string; value: string; extra: string[] } | null = null;

  const flush = () => {
    if (!current) return;
    const hasExtra = current.extra.some((l) => l.trim() !== '');
    fields.push({
      label: current.label,
      raw: current.raw,
      text: [current.value, ...current.extra].join('\n').trim(),
      isEmpty: current.value === '' && !hasExtra
    });
    current = null;
  };

  for (const line of lines) {
    const match = matchFieldLine(line);
    if (match) {
      flush();
      current = { label: match.label, raw: line, value: match.value, extra: [] };
      continue;
    }
    if (!current) continue;
    if (line.trim() === '') {
      current.extra.push(line);
      continue;
    }
    const indent = line.length - line.trimStart().length;
    if (indent >= FIELD_INDENT_LIMIT) {
      current.extra.push(line);
    } else {
      // Top-level, non-field content (e.g. a trailing "---") ends this field's answer.
      flush();
    }
  }
  flush();
  return fields;
}

function extractTier(body: string, fields: FieldEntry[]): RiskTier | null {
  // When an explicit "Tier" field exists, it is authoritative - a fallback body search would
  // pick up incidental mentions like "(tier below high)" in the sign-off or justification.
  const tierField = fields.find((f) => /^tier\b/i.test(f.label));
  const haystacks: string[] = [];
  if (tierField) {
    haystacks.push(tierField.text);
  } else {
    // Fallback for specs that don't use the bold-field convention.
    const fieldLine = body
      .split(/\r?\n/)
      .find((l) => /\*\*tier\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l));
    haystacks.push(fieldLine ?? body);
  }
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

function extractSignoff(body: string, fields: FieldEntry[]): string {
  const signoffField = fields.find((f) => /^sign[- ]?off\b/i.test(f.label));
  if (signoffField) return signoffField.text;
  // Fallback for specs that don't use the bold-field convention.
  const signoffLine = body
    .split(/\r?\n/)
    .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
  return signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
}

function answeredText(body: string, fields: FieldEntry[]): string {
  const emptyRawLines = new Set(fields.filter((f) => f.isEmpty).map((f) => f.raw));
  return body
    .split(/\r?\n/)
    .filter((l) => !emptyRawLines.has(l))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const answered = answeredText(body);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const emptyFields = body.split(/\r?\n/).filter((l) => EMPTY_FIELD.test(l));
    for (const line of emptyFields) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffLine = body
          .split(/\r?\n/)
          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

